function (values, root) {
  var code = Number(values.code);
  var family = Math.floor(code / 100);
  var families = {
    1: "1xx: the server is still working",
    2: "2xx: it worked",
    3: "3xx: look somewhere else",
    4: "4xx: the request is wrong",
    5: "5xx: the server is wrong"
  };
  var named = {
    200: "The request worked and the answer is in the body.",
    301: "The thing moved. Ask again at the new address.",
    400: "The bytes you sent do not parse.",
    401: "No usable login came with the request.",
    403: "You are known, and you are still not allowed.",
    404: "There is nothing at that address.",
    500: "The request was fine and the handler failed.",
    502: "The server behind this one answered badly."
  };
  root.querySelector("[data-code]").textContent = code;
  root.querySelector("[data-family]").textContent = families[family] || "not a real family";
  root.querySelector("[data-meaning]").textContent = named[code] || "Slide to 200, 301, 400, 401, 403, 404, 500 or 502 for a named example.";
}

(function () {
  var frames = [
    ["Step 1 of 4: the client asks", "GET /old-page", "The client has asked for the address it was given, and it waits."],
    ["Step 2 of 4: the reply", "301 Moved Permanently", "The body is empty. A Location header names the new address."],
    ["Step 3 of 4: the client asks again", "GET /new-page", "Same request, sent to the address the reply named."],
    ["Step 4 of 4: the answer", "200 OK", "The page arrives, one extra round trip later."]
  ];
  var at = 0;
  return function (values, root, changed) {
    if (changed === "reset") at = 0;
    else if (changed === "step") at = Math.min(at + 1, frames.length - 1);
    var f = frames[at];
    root.querySelector("[data-head]").textContent = f[0];
    root.querySelector("[data-line]").textContent = f[1];
    root.querySelector("[data-note]").textContent = f[2];
    var nodes = root.querySelectorAll("[data-node]");
    for (var i = 0; i < nodes.length; i += 1) {
      nodes[i].style.background = i <= at ? "var(--accent)" : "var(--border)";
    }
  };
})()
